// Rebuild the embedded offline font from the licensed source shipped with the app.
import { readFile, writeFile } from "node:fs/promises";
const font = await readFile(
  new URL(
    "../public/design-preview/fonts/PretendardVariable.woff2",
    import.meta.url,
  ),
);
const license = await readFile(
  new URL("../public/design-preview/fonts/LICENSE.txt", import.meta.url),
  "utf8",
);
await writeFile(
  new URL("../src/lib/guidebook-font.ts", import.meta.url),
  "// Generated by scripts/build-guidebook-font.mjs. Pretendard v1.3.9, SIL OFL 1.1.\n" +
    "// License: public/design-preview/fonts/LICENSE.txt\n" +
    'export const guidebookFont = "data:font/woff2;base64,' +
    font.toString("base64") +
    '";\n' +
    "export const guidebookFontLicense = " +
    JSON.stringify(license) +
    ";\n",
);
